import java.util.*;

public class Main {
    static int n, mod;
    static Map<Integer, Integer>[][][] memo;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        mod = sc.nextInt();

        // Initialize memo array
        memo = new HashMap[2][n + 1][];
        for (int i = 0; i < 2; i++) {
            for (int j = 0; j <= n; j++) {
                memo[i][j] = new HashMap[2 * n + 1];
                for (int k = 0; k < 2 * n + 1; k++) {
                    memo[i][j][k] = new HashMap<>();
                }
            }
        }

        int answer = solve(n, 0, true);
        System.out.println(answer % mod);
        sc.close();
    }

    static int invnum(int[] seq) {
        int count = 0;
        for (int i = 0; i < seq.length; i++) {
            for (int j = i + 1; j < seq.length; j++) {
                if (seq[i] > seq[j]) {
                    count++;
                }
            }
        }
        return count;
    }

    static int[] generatePermutation(int N, int[] current, boolean[] used, int depth) {
        if (depth == N) {
            return current.clone();
        }
        for (int i = 0; i < N; i++) {
            if (!used[i]) {
                used[i] = true;
                current[depth] = i;
                int[] result = generatePermutation(N, current, used, depth + 1);
                if (result != null) {
                    return result;
                }
                used[i] = false;
            }
        }
        return null;
    }

    static int solve(int N, int K, boolean flag) {
        int indexK = K + 2 * N; // shift for indexing
        if (memo[flag ? 1 : 0][N][indexK].containsKey(K)) {
            return memo[flag ? 1 : 0][N][indexK].get(K);
        }
        if (N == 1) {
            int res = 0;
            if (!flag && K < 0) {
                res = 1;
            }
            memo[flag ? 1 : 0][N][indexK].put(K, res);
            return res;
        }
        int invnum_INF = (N * (N - 1)) / 2;
        if (K < -invnum_INF - 1) {
            int res = solve(N, -invnum_INF - 1, flag);
            memo[flag ? 1 : 0][N][indexK].put(K, res);
            return res;
        }
        if (K >= invnum_INF) {
            memo[flag ? 1 : 0][N][indexK].put(K, 0);
            return 0;
        }
        int total = 0;
        for (int delta = -N + 1; delta < N; delta++) {
            if (flag && delta > 0) {
                continue;
            }
            int weight = Math.min(N - delta, delta + N);
            total += solve(N - 1, K - delta, flag && delta == 0) * weight;
            total %= mod;
        }
        memo[flag ? 1 : 0][N][indexK].put(K, total);
        return total;
    }
}
